WITH filtered AS (SELECT *, quantity + unit_price AS line_total FROM order_items WHERE product_id IS NOT NULL) SELECT order_id, BIT_OR(quantity) AS quantity_bit_or, COUNT(*) AS row_count, APPROX_PERCENTILE(unit_price, ARRAY(0.25, 0.5, 0.75)) AS unit_price_quartiles, APPROX_PERCENTILE(line_total, 0.5) AS line_total_p50, APPROX_PERCENTILE(unit_price, ARRAY(0.25, 0.5, 0.75)) AS unit_price_quartiles_2 FROM filtered GROUP BY order_id ORDER BY order_id NULLS LAST
